mapper.select:
SELECT id, admin_id, username, module, operation, method, path, params, success, error_msg,
       cost_ms, trace_id, ip, user_agent, created_at
FROM sys_operation_log

  AND admin_id = #{adminId}
  AND module = #{module}
  AND success = #{success}
  AND created_at >= #{start}
  AND created_at <= #{end}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM sys_operation_log

  AND admin_id = #{adminId}
  AND module = #{module}
  AND success = #{success}
  AND created_at >= #{start}
  AND created_at <= #{end}
